using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using LifeVerse.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Economy;

public sealed record PublishProductRequest(Guid AssetId, string Name, string Description, string Category, long PriceCoins, string? ImageUrl, string? PermissionsJson);
public sealed record PurchaseRequest(string IdempotencyKey);
public sealed record TransferRequest(Guid RecipientUserId, long AmountCoins, string IdempotencyKey);
public sealed record RentalRequest(Guid PlanId, string IdempotencyKey);
public sealed record StoreRequest(Guid ProductId, Guid? ObjectId, string DisplayName);

public static class EconomyEndpoints
{
    private const long FeeBps = 500;
    public static IEndpointRouteBuilder MapEconomyEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var economy = endpoints.MapGroup("/api/v1/economy").WithTags("Economy").RequireAuthorization();
        economy.MapGet("/wallet", WalletAsync); economy.MapGet("/wallet/transactions", TransactionsAsync); economy.MapPost("/transfer", TransferAsync);
        economy.MapGet("/products", ProductsAsync); economy.MapPost("/products", PublishAsync); economy.MapPatch("/products/{id:guid}", UpdateProductAsync); economy.MapPost("/products/{id:guid}/deactivate", DeactivateAsync); economy.MapPost("/products/{id:guid}/purchase", PurchaseAsync); economy.MapGet("/orders", OrdersAsync);
        economy.MapGet("/rental-plans", RentalPlansAsync); economy.MapPost("/islands/{islandId:guid}/rent", RentIslandAsync); economy.MapPost("/rentals/{rentalId:guid}/renew", RenewRentalAsync);
        economy.MapGet("/islands/{islandId:guid}/stores", ListStoresAsync); economy.MapPost("/islands/{islandId:guid}/stores", CreateStoreAsync); economy.MapDelete("/islands/{islandId:guid}/stores/{storeId:guid}", DeleteStoreAsync);
        return endpoints;
    }
    private static async Task<IResult> WalletAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var wallet = await EnsureWallet(db, me, ct); return Results.Ok(new { wallet.Id, wallet.AvailableCoins, wallet.IsBlocked, wallet.UpdatedAt }); }
    private static async Task<IResult> TransactionsAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); return Results.Ok(await db.LedgerTransactions.AsNoTracking().Where(x => x.InitiatorUserId == me).OrderByDescending(x => x.CreatedAt).Take(100).ToListAsync(ct)); }
    private static async Task<IResult> ProductsAsync(string? q, string? category, int page, int pageSize, LifeVerseDbContext db, CancellationToken ct) { page = Math.Max(1, page); pageSize = Math.Clamp(pageSize == 0 ? 24 : pageSize, 1, 100); var query = db.MarketplaceProducts.AsNoTracking().Where(x => x.Status == "active"); if (!string.IsNullOrWhiteSpace(q)) query = query.Where(x => x.Name.ToLower().Contains(q.ToLower()) || x.Description.ToLower().Contains(q.ToLower())); if (!string.IsNullOrWhiteSpace(category)) query = query.Where(x => x.Category == category); var total = await query.CountAsync(ct); return Results.Ok(new { page, pageSize, total, items = await query.OrderByDescending(x => x.UpdatedAt).Skip((page - 1) * pageSize).Take(pageSize).ToListAsync(ct) }); }
    private static async Task<IResult> ListStoresAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == me), ct)) return Results.Forbid(); return Results.Ok(await db.WorldStores.AsNoTracking().Where(x => x.IslandId == islandId && x.DeletedAt == null).Join(db.MarketplaceProducts, s => s.ProductId, p => p.Id, (s, p) => new { store = s, product = p }).Where(x => x.product.Status == "active").ToListAsync(ct)); }
    private static async Task<IResult> CreateStoreAsync(Guid islandId, StoreRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await db.Islands.AnyAsync(x => x.Id == islandId && x.OwnerUserId == me && x.DeletedAt == null, ct)) return Results.Forbid(); if (!await db.MarketplaceProducts.AnyAsync(x => x.Id == request.ProductId && x.SellerUserId == me && x.Status == "active", ct) || request.DisplayName.Trim().Length is < 1 or > 160) return Results.BadRequest(); var item = new WorldStore { Id = Guid.NewGuid(), IslandId = islandId, OwnerUserId = me, ProductId = request.ProductId, ObjectId = request.ObjectId, DisplayName = request.DisplayName.Trim(), CreatedAt = clock.GetUtcNow(), UpdatedAt = clock.GetUtcNow() }; db.WorldStores.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/economy/islands/{islandId}/stores/{item.Id}", item); }
    private static async Task<IResult> DeleteStoreAsync(Guid islandId, Guid storeId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.WorldStores.SingleOrDefaultAsync(x => x.Id == storeId && x.IslandId == islandId && x.OwnerUserId == me && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); item.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> PublishAsync(PublishProductRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.PriceCoins < 0 || request.Name.Trim().Length is < 1 or > 160 || !await db.Assets.AnyAsync(x => x.Id == request.AssetId && x.OwnerUserId == me && x.DeletedAt == null, ct)) return Results.BadRequest(); var item = new MarketplaceProduct { Id = Guid.NewGuid(), SellerUserId = me, AssetId = request.AssetId, Name = request.Name.Trim(), Description = request.Description[..Math.Min(4000, request.Description.Length)], Category = request.Category.Trim()[..Math.Min(48, request.Category.Trim().Length)], PriceCoins = request.PriceCoins, ImageUrl = request.ImageUrl, PermissionsJson = request.PermissionsJson ?? "{}", Status = "active", Version = 1, CreatedAt = clock.GetUtcNow(), UpdatedAt = clock.GetUtcNow() }; db.MarketplaceProducts.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/economy/products/{item.Id}", item); }
    private static async Task<IResult> UpdateProductAsync(Guid id, PublishProductRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.MarketplaceProducts.SingleOrDefaultAsync(x => x.Id == id && x.SellerUserId == me && x.Status == "active", ct); if (item is null) return Results.NotFound(); if (request.PriceCoins < 0 || request.Name.Trim().Length is < 1 or > 160) return Results.BadRequest(); item.Name = request.Name.Trim(); item.Description = request.Description[..Math.Min(4000, request.Description.Length)]; item.Category = request.Category.Trim()[..Math.Min(48, request.Category.Trim().Length)]; item.PriceCoins = request.PriceCoins; item.ImageUrl = request.ImageUrl; item.PermissionsJson = request.PermissionsJson ?? item.PermissionsJson; item.Version++; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> DeactivateAsync(Guid id, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.MarketplaceProducts.SingleOrDefaultAsync(x => x.Id == id && x.SellerUserId == me, ct); if (item is null) return Results.NotFound(); item.Status = "inactive"; await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> OrdersAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); return Results.Ok(await db.MarketplaceOrders.AsNoTracking().Where(x => x.BuyerUserId == me || x.SellerUserId == me).OrderByDescending(x => x.CreatedAt).Take(100).ToListAsync(ct)); }
    private static async Task<IResult> PurchaseAsync(Guid id, PurchaseRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.IdempotencyKey.Length is < 8 or > 128) return Results.BadRequest(); await using var tx = await db.Database.BeginTransactionAsync(ct); var existing = await db.MarketplaceOrders.SingleOrDefaultAsync(x => x.IdempotencyKey == request.IdempotencyKey, ct); if (existing is not null) return Results.Ok(existing); var product = await db.MarketplaceProducts.SingleOrDefaultAsync(x => x.Id == id && x.Status == "active", ct); if (product is null) return Results.NotFound(); if (product.SellerUserId == me) return Results.BadRequest(new { error = "cannot_buy_own_product" }); var buyer = await EnsureWallet(db, me, ct); var seller = await EnsureWallet(db, product.SellerUserId, ct); if (buyer.IsBlocked || seller.IsBlocked) return Results.Forbid(); if (buyer.AvailableCoins < product.PriceCoins) return Results.Conflict(new { error = "insufficient_balance" }); var now = clock.GetUtcNow(); var transaction = new LedgerTransaction { Id = Guid.NewGuid(), IdempotencyKey = request.IdempotencyKey, Type = "marketplace_purchase", Status = "completed", Amount = product.PriceCoins, InitiatorUserId = me, MetadataJson = JsonSerializer.Serialize(new { productId = id }), CreatedAt = now, CompletedAt = now }; db.LedgerTransactions.Add(transaction); var fee = product.PriceCoins * FeeBps / 10000; buyer.AvailableCoins -= product.PriceCoins; seller.AvailableCoins += product.PriceCoins - fee; buyer.UpdatedAt = seller.UpdatedAt = now; var buyerAccount = await EnsureAccount(db, me, "user"); var sellerAccount = await EnsureAccount(db, product.SellerUserId, "user"); var treasury = await EnsureAccount(db, null, "treasury"); db.LedgerEntries.AddRange(new LedgerEntry { Id = Guid.NewGuid(), TransactionId = transaction.Id, AccountId = buyerAccount.Id, Debit = product.PriceCoins, Credit = 0, CreatedAt = now }, new LedgerEntry { Id = Guid.NewGuid(), TransactionId = transaction.Id, AccountId = sellerAccount.Id, Debit = 0, Credit = product.PriceCoins - fee, CreatedAt = now }, new LedgerEntry { Id = Guid.NewGuid(), TransactionId = transaction.Id, AccountId = treasury.Id, Debit = 0, Credit = fee, CreatedAt = now }); var item = new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = me, AssetId = product.AssetId, DisplayName = product.Name, CreatedAt = now, UpdatedAt = now }; db.InventoryItems.Add(item); var order = new MarketplaceOrder { Id = Guid.NewGuid(), ProductId = product.Id, BuyerUserId = me, SellerUserId = product.SellerUserId, PriceCoins = product.PriceCoins, Status = "completed", IdempotencyKey = request.IdempotencyKey, TransactionId = transaction.Id, InventoryItemId = item.Id, CreatedAt = now, CompletedAt = now }; db.MarketplaceOrders.Add(order); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Results.Ok(order); }
    private static async Task<IResult> TransferAsync(TransferRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me) || me == request.RecipientUserId || request.AmountCoins <= 0 || request.IdempotencyKey.Length is < 8 or > 128) return Results.BadRequest(); await using var tx = await db.Database.BeginTransactionAsync(ct); if (await db.LedgerTransactions.AnyAsync(x => x.IdempotencyKey == request.IdempotencyKey, ct)) return Results.Ok(new { status = "already_processed" }); var recipient = await db.Users.AnyAsync(x => x.Id == request.RecipientUserId && x.DeletedAt == null, ct); if (!recipient) return Results.NotFound(); var senderWallet = await EnsureWallet(db, me, ct); var recipientWallet = await EnsureWallet(db, request.RecipientUserId, ct); if (senderWallet.IsBlocked || recipientWallet.IsBlocked || senderWallet.AvailableCoins < request.AmountCoins) return Results.Conflict(new { error = "transfer_rejected" }); var now = clock.GetUtcNow(); senderWallet.AvailableCoins -= request.AmountCoins; recipientWallet.AvailableCoins += request.AmountCoins; senderWallet.UpdatedAt = recipientWallet.UpdatedAt = now; db.LedgerTransactions.Add(new LedgerTransaction { Id = Guid.NewGuid(), IdempotencyKey = request.IdempotencyKey, Type = "user_transfer", Status = "completed", Amount = request.AmountCoins, InitiatorUserId = me, MetadataJson = JsonSerializer.Serialize(new { recipientUserId = request.RecipientUserId }), CreatedAt = now, CompletedAt = now }); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Results.Ok(new { status = "completed", amountCoins = request.AmountCoins }); }
    private static async Task<IResult> RentalPlansAsync(LifeVerseDbContext db, CancellationToken ct) => Results.Ok(await db.IslandRentalPlans.AsNoTracking().Where(x => x.IsActive).ToListAsync(ct));
    private static async Task<IResult> RentIslandAsync(Guid islandId, RentalRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var plan = await db.IslandRentalPlans.SingleOrDefaultAsync(x => x.Id == request.PlanId && x.IsActive, ct); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.OwnerUserId == me && x.DeletedAt == null, ct); if (plan is null || island is null) return Results.NotFound(); var wallet = await EnsureWallet(db, me, ct); if (wallet.AvailableCoins < plan.PriceCoins) return Results.Conflict(new { error = "insufficient_balance" }); var now = clock.GetUtcNow(); wallet.AvailableCoins -= plan.PriceCoins; wallet.UpdatedAt = now; db.IslandRentals.Add(new IslandRental { Id = Guid.NewGuid(), IslandId = islandId, UserId = me, PlanId = plan.Id, StartsAt = now, ExpiresAt = now.AddDays(plan.DurationDays), RecoveryUntil = now.AddDays(plan.DurationDays + 7), Status = "active" }); db.LedgerTransactions.Add(new LedgerTransaction { Id = Guid.NewGuid(), IdempotencyKey = request.IdempotencyKey, Type = "island_rental", Status = "completed", Amount = plan.PriceCoins, InitiatorUserId = me, CreatedAt = now, CompletedAt = now }); await db.SaveChangesAsync(ct); return Results.Ok(new { status = "active", expiresAt = now.AddDays(plan.DurationDays) }); }
    private static async Task<IResult> RenewRentalAsync(Guid rentalId, RentalRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var rental = await db.IslandRentals.SingleOrDefaultAsync(x => x.Id == rentalId && x.UserId == me && x.Status == "active", ct); if (rental is null) return Results.NotFound(); var plan = await db.IslandRentalPlans.SingleAsync(x => x.Id == rental.PlanId, ct); var wallet = await EnsureWallet(db, me, ct); if (wallet.AvailableCoins < plan.PriceCoins) return Results.Conflict(new { error = "insufficient_balance" }); var now = clock.GetUtcNow(); wallet.AvailableCoins -= plan.PriceCoins; wallet.UpdatedAt = now; rental.ExpiresAt = rental.ExpiresAt.AddDays(plan.DurationDays); rental.RecoveryUntil = rental.ExpiresAt.AddDays(7); db.LedgerTransactions.Add(new LedgerTransaction { Id = Guid.NewGuid(), IdempotencyKey = request.IdempotencyKey, Type = "island_rental_renewal", Status = "completed", Amount = plan.PriceCoins, InitiatorUserId = me, CreatedAt = now, CompletedAt = now }); await db.SaveChangesAsync(ct); return Results.Ok(rental); }
    private static async Task<Wallet> EnsureWallet(LifeVerseDbContext db, Guid userId, CancellationToken ct) { var wallet = await db.Wallets.SingleOrDefaultAsync(x => x.UserId == userId, ct); if (wallet is not null) return wallet; wallet = new Wallet { Id = Guid.NewGuid(), UserId = userId, AvailableCoins = 0, CreatedAt = DateTimeOffset.UtcNow, UpdatedAt = DateTimeOffset.UtcNow }; db.Wallets.Add(wallet); await db.SaveChangesAsync(ct); return wallet; }
    private static async Task<LedgerAccount> EnsureAccount(LifeVerseDbContext db, Guid? userId, string type) { var account = await db.LedgerAccounts.SingleOrDefaultAsync(x => x.UserId == userId && x.AccountType == type); if (account is not null) return account; account = new LedgerAccount { Id = Guid.NewGuid(), UserId = userId, AccountType = type, CreatedAt = DateTimeOffset.UtcNow }; db.LedgerAccounts.Add(account); await db.SaveChangesAsync(); return account; }
    private static bool User(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirstValue(JwtRegisteredClaimNames.Sub), out id);
}
